-- Standalone FTS5 indexes with stable integer keys (source tables use UUID primary keys; VACUUM may change their rowids).
CREATE TABLE ce_forum_fts_keys (id INTEGER PRIMARY KEY, kind TEXT NOT NULL, source_id TEXT NOT NULL, tag TEXT NOT NULL DEFAULT '', UNIQUE(kind,source_id,tag));
CREATE VIRTUAL TABLE ce_forum_fts_threads USING fts5(title,prefix, tokenize='unicode61 remove_diacritics 2');
INSERT INTO ce_forum_fts_keys(kind,source_id,tag) SELECT 'thread',id,'' FROM ce_forum_threads;
INSERT INTO ce_forum_fts_threads(rowid,title,prefix) SELECT k.id,s.title,s.prefix FROM ce_forum_threads s JOIN ce_forum_fts_keys k ON k.kind='thread' AND k.source_id=s.id;
CREATE TRIGGER ce_forum_fts_threads_ai AFTER INSERT ON ce_forum_threads BEGIN INSERT INTO ce_forum_fts_keys(kind,source_id,tag) VALUES('thread',new.id,''); INSERT INTO ce_forum_fts_threads(rowid,title,prefix) SELECT id,new.title,new.prefix FROM ce_forum_fts_keys WHERE kind='thread' AND source_id=new.id AND tag=''; END;
CREATE TRIGGER ce_forum_fts_threads_ad AFTER DELETE ON ce_forum_threads BEGIN DELETE FROM ce_forum_fts_threads WHERE rowid=(SELECT id FROM ce_forum_fts_keys WHERE kind='thread' AND source_id=old.id AND tag=''); DELETE FROM ce_forum_fts_keys WHERE kind='thread' AND source_id=old.id AND tag=''; END;
CREATE TRIGGER ce_forum_fts_threads_au AFTER UPDATE OF title,prefix,id ON ce_forum_threads WHEN old.title IS NOT new.title OR old.prefix IS NOT new.prefix OR old.id IS NOT new.id BEGIN DELETE FROM ce_forum_fts_threads WHERE rowid=(SELECT id FROM ce_forum_fts_keys WHERE kind='thread' AND source_id=old.id AND tag=''); UPDATE ce_forum_fts_keys SET source_id=new.id,tag='' WHERE kind='thread' AND source_id=old.id AND tag=''; INSERT INTO ce_forum_fts_threads(rowid,title,prefix) SELECT id,new.title,new.prefix FROM ce_forum_fts_keys WHERE kind='thread' AND source_id=new.id AND tag=''; END;
CREATE VIRTUAL TABLE ce_forum_fts_posts USING fts5(body, tokenize='unicode61 remove_diacritics 2');
INSERT INTO ce_forum_fts_keys(kind,source_id,tag) SELECT 'post',id,'' FROM ce_forum_posts;
INSERT INTO ce_forum_fts_posts(rowid,body) SELECT k.id,s.body FROM ce_forum_posts s JOIN ce_forum_fts_keys k ON k.kind='post' AND k.source_id=s.id;
CREATE TRIGGER ce_forum_fts_posts_ai AFTER INSERT ON ce_forum_posts BEGIN INSERT INTO ce_forum_fts_keys(kind,source_id,tag) VALUES('post',new.id,''); INSERT INTO ce_forum_fts_posts(rowid,body) SELECT id,new.body FROM ce_forum_fts_keys WHERE kind='post' AND source_id=new.id AND tag=''; END;
CREATE TRIGGER ce_forum_fts_posts_ad AFTER DELETE ON ce_forum_posts BEGIN DELETE FROM ce_forum_fts_posts WHERE rowid=(SELECT id FROM ce_forum_fts_keys WHERE kind='post' AND source_id=old.id AND tag=''); DELETE FROM ce_forum_fts_keys WHERE kind='post' AND source_id=old.id AND tag=''; END;
CREATE TRIGGER ce_forum_fts_posts_au AFTER UPDATE OF body,id ON ce_forum_posts WHEN old.body IS NOT new.body OR old.id IS NOT new.id BEGIN DELETE FROM ce_forum_fts_posts WHERE rowid=(SELECT id FROM ce_forum_fts_keys WHERE kind='post' AND source_id=old.id AND tag=''); UPDATE ce_forum_fts_keys SET source_id=new.id,tag='' WHERE kind='post' AND source_id=old.id AND tag=''; INSERT INTO ce_forum_fts_posts(rowid,body) SELECT id,new.body FROM ce_forum_fts_keys WHERE kind='post' AND source_id=new.id AND tag=''; END;
CREATE VIRTUAL TABLE ce_forum_fts_tags USING fts5(tag, tokenize='unicode61 remove_diacritics 2');
INSERT INTO ce_forum_fts_keys(kind,source_id,tag) SELECT 'tag',thread_id,tag FROM ce_forum_thread_tags;
INSERT INTO ce_forum_fts_tags(rowid,tag) SELECT k.id,s.tag FROM ce_forum_thread_tags s JOIN ce_forum_fts_keys k ON k.kind='tag' AND k.source_id=s.thread_id AND k.tag=s.tag;
CREATE TRIGGER ce_forum_fts_tags_ai AFTER INSERT ON ce_forum_thread_tags BEGIN INSERT INTO ce_forum_fts_keys(kind,source_id,tag) VALUES('tag',new.thread_id,new.tag); INSERT INTO ce_forum_fts_tags(rowid,tag) SELECT id,new.tag FROM ce_forum_fts_keys WHERE kind='tag' AND source_id=new.thread_id AND tag=new.tag; END;
CREATE TRIGGER ce_forum_fts_tags_ad AFTER DELETE ON ce_forum_thread_tags BEGIN DELETE FROM ce_forum_fts_tags WHERE rowid=(SELECT id FROM ce_forum_fts_keys WHERE kind='tag' AND source_id=old.thread_id AND tag=old.tag); DELETE FROM ce_forum_fts_keys WHERE kind='tag' AND source_id=old.thread_id AND tag=old.tag; END;
CREATE TRIGGER ce_forum_fts_tags_au AFTER UPDATE OF tag,thread_id ON ce_forum_thread_tags WHEN old.tag IS NOT new.tag OR old.thread_id IS NOT new.thread_id BEGIN DELETE FROM ce_forum_fts_tags WHERE rowid=(SELECT id FROM ce_forum_fts_keys WHERE kind='tag' AND source_id=old.thread_id AND tag=old.tag); UPDATE ce_forum_fts_keys SET source_id=new.thread_id,tag=new.tag WHERE kind='tag' AND source_id=old.thread_id AND tag=old.tag; INSERT INTO ce_forum_fts_tags(rowid,tag) SELECT id,new.tag FROM ce_forum_fts_keys WHERE kind='tag' AND source_id=new.thread_id AND tag=new.tag; END;
